Replace the `if not self.required:` block so it does not double-wrap metavars that already indicate optionality/brackets:

```python
    def make_metavar(self, ctx: Context) -> str:
        if self.metavar is not None:
            return self.metavar
        var = self.type.get_metavar(param=self, ctx=ctx)
        if not var:
            var = self.name.upper()
        if self.deprecated:
            var += "!"
        if not self.required and not (var.startswith("[") and var.endswith("]")):
            var = f"[{var}]"
        if self.nargs != 1:
            var += "..."
        return var
```

